(function(root){const data=typeof module!=='undefined'?require('./bapa-data.js'):root.BAPAData;
function fresh(id='equipment'){return {version:2,caseId:id,read:[],checks:{},method:'',critical:false,history:[],topics:{},proposal:'',outcome:null,notes:''}}
function get(s){return data.cases.find(c=>c.id===s.caseId)||data.cases[0]}
function ready(s){const c=get(s),gaps=[];if(c.files.some(f=>!s.read.includes(f[0])))gaps.push('閱讀五份本輪證據卡');if(c.check.some((q,i)=>s.checks[i]===undefined||Number(s.checks[i])!==q[2]))gaps.push('完成三項事實檢核並修正錯誤');if(s.method!==c.method)gaps.push('選擇有本輪資料支持的最適方法');if(!s.critical)gaps.push('確認協議年度、範圍、關鍵假設及重談條款');if(!s.topics.function||!s.topics.method||!s.topics.rate)gaps.push('完成實質功能、方法與利潤率三種雙邊攻防');return gaps}
function amounts(s,value){const c=get(s),v=Number(value);if(String(value).trim()===''||!Number.isFinite(v)||v<0||v>100)return null;let tw,other,formula;if(c.id==='chemical-shared'){tw=3000+c.base*v/100;other=c.pool-tw;formula='臺灣3,000＋剩餘55,000 × '+v.toFixed(2)+'%'}else if(c.id==='marketing'){other=c.base*v/100;tw=c.pool-other;formula='義方100,000 × '+v.toFixed(2)+'%；臺灣＝15,000－義方報酬'}else if(c.id==='hub'){other=c.base*v/100;tw=c.pool-other;formula='荷方200,000 × '+v.toFixed(2)+'%；臺灣＝20,000－荷方報酬'}else {tw=c.base*v/100+(c.id==='manufacturing'?0:0);other=c.pool-tw;formula=c.base.toLocaleString('en-US')+' × '+v.toFixed(2)+'%'+''}tw=Math.round(tw);other=Math.round(other);return {tw,other,delta:tw-c.reported,pool:c.pool,formula,valid:tw>=0&&other>=0}}
function evaluate(s,choice){const c=get(s),gaps=ready(s),a=amounts(s,s.proposal);if(choice==='adjourn')return {kind:'adjourn',title:'保留歧見，補件續談',reason:'未將未解決問題寫成已合意；保留雙方立場、所缺文據與下次議程。',gaps,amounts:a,agreed:false};if(gaps.length||!a||!a.valid)return {kind:'incomplete',title:'尚不能形成協議草案',reason:!a?'請先填入本輪提案。':!a.valid?'提案使同範圍一方利潤變成負值，需重查模型與事實。':'還缺少支持提案的必要步驟。',gaps,agreed:false};if(Number(s.proposal)<c.min||Number(s.proposal)>c.max)return {kind:'dispute',title:'數值仍無證據支持，保留歧見',reason:'本輪資料支持'+c.min.toFixed(2)+'%–'+c.max.toFixed(2)+'%。不能靠取雙方開價平均或施壓形成常規結果；可補新比較資料再談。',amounts:a,agreed:false};if(choice==='partial')return {kind:'partial',title:'形成部分合意／方法共識',reason:'目前僅就本輪方法、口徑與提案形成模擬共識；其他交易、年度或執行條件不視為已解決。',amounts:a,agreed:false};return {kind:'agreement',title:'雙方接受教學協議草案',reason:'本輪事實、方法、範圍及關鍵假設有給定證據支持，提案落在本輪支持範圍。這是教學角色回應，不是真實主管機關同意、核定或簽署。',amounts:a,agreed:true}}
function intent(q){const x=String(q).normalize('NFKC').toLowerCase();if(/50.?50|一人一半|平均開價|取平均|折衷|各退一步/.test(x))return 'midpoint';if(/拍桌|吵|滾|笨|不讓步|一定要|接受就好/.test(x))return 'tension';if(/假設|年度|範圍|重談|續貸|執行|監測/.test(x))return 'critical';if(/利潤率|多少|[0-9].*%|留.*利潤|開價|保留.*利潤/.test(x))return 'rate';if(/材料|零件|分母|成本基礎|代購|轉付/.test(x))return 'method';if(/原液.*(價格|賣|貴|便宜)|原料.*(成本|價格)|傳統交易價格/.test(x))return 'price';if(/dempe|無形|專利|商標|技術|平台|權利|品牌/.test(x))return 'asset';if(/方法|可比|比較|cup|tnmm|分割|樣本/.test(x))return 'method';if(/功能|風險|決策|控制|承擔|工程|受託|有限|還款|信評|信用|隱含/.test(x))return 'function';if(/反證|不認同|不同意|憑什麼|為何|為什麼|如何|怎麼/.test(x))return 'rebuttal';return 'clarify'}
const editorial=typeof module!=='undefined'?require('./bapa-editorial.js'):root.BAPAEditorial;
function talk(s,q,forced){const c=get(s),k=forced||intent(q),n=s.topics[k]||0;let lines=[];if(c.attack[k]){if(n>=3)return {topic:k,lines:[],skip:true,note:'這項爭點的立場、補核與橋接已談完。請帶新證據續談，或形成草案／保留歧見。'};const voices=n===0?c.attack[k]:n===1?(editorial.follow[c.id]?.[k]||[c.why,'這點請先以本輪資料核對；沒有新文據時，不改寫目前前提。']):['先把目前提案寫到橋接表：'+(String(s.proposal).trim()===''?'還沒有填入數值，現在不先替雙方決定答案。':Number(s.proposal).toFixed(2)+'%。我方會按同範圍所得檢查，不能只看比率。'),'如果資料與關鍵假設都齊了，可以提出草案。仍未解決的權利、口徑或年度，請明列為保留，不用再重演開價。'];lines=[{speaker:'阿芬｜臺方',text:voices[0]},{speaker:c.delegate+'｜'+c.country+'代表',text:voices[1]}];}else if(k==='critical')lines=[{speaker:'王衡｜議程確認',text:c.files[4][2]},{speaker:c.delegate+'｜'+c.country+'代表',text:'我方要求把這些條件寫入草案，也保留未涵蓋交易與年度；不能只握手就當作所有爭議都解決。'}];else if(k==='midpoint')lines=[{speaker:c.delegate+'｜'+c.country+'代表',text:'我方不接受把兩個開價平均就叫常規。請解釋可比資料與實際功能如何支持該數值。'},{speaker:'阿芬｜臺方',text:'同意，協商可解決不確定性，但不能用50對50取代事實與方法。'+c.why}];else if(k==='tension')lines=[{speaker:'阿芬｜臺方',text:'我方保留立場，但提高音量不會補足功能、風險與比較資料。請指出對方哪一項事實或方法錯誤。'},{speaker:c.delegate+'｜'+c.country+'代表',text:'我方也不同意無條件接受。可以休會，但請把具體歧見、所需補件與續談條件留下。'}];else if(k==='rebuttal')lines=[{speaker:c.delegate+'｜'+c.country+'代表',text:'我方的實質反駁是：'+c.attack.asset[1]},{speaker:'阿芬｜臺方',text:'我方回應：'+c.attack.method[0]+' 請對照'+c.files[2][0]+'，而非只看一方想留的利潤。'}];else lines=[{speaker:'王衡｜釐清問題',text:'你問的「'+String(q).slice(0,240)+'」目前不能對上已寫明的本輪問題。我不會編造回答。可具體問功能風險、無形資產、可比方法、利潤率或關鍵假設；未答細節保留補件。'}];if(lines.every(line=>s.history.some(h=>h.text===line.text)))return {topic:k,lines:[],skip:true,note:'這一點已在筆錄裡。可以改問具體文據，或先記錄尚未解決的問題。'};s.history.push({speaker:'你｜臺方談判席',text:String(q).slice(0,400)},...lines);s.topics[k]=n+1;s.outcome=null;return {topic:k,lines}}
const api={fresh,get,ready,amounts,evaluate,intent,talk};if(typeof module!=='undefined')module.exports=api;else root.BAPALogic=api;
})(typeof window!=='undefined'?window:globalThis);
